q.push(new A.J("bc_staccato",6,"\u0421\u0442\u0430\u043a\u043a\u0430\u0442\u043e","\u0411\u043e\u043d\u0443\u0441\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u043e\u0442\u0437\u044b\u0432\u0430\u0435\u0442\u0435 \u0432\u0441\u0435 \u041a\u043b\u0438\u043d\u043a\u0438 \u0431\u0430\u0440\u0434\u0430 \u2014 \u043e\u043d\u0438 \u043b\u0435\u0442\u044f\u0442 \u043a \u0432\u0430\u043c \u043f\u043e \u043f\u0440\u044f\u043c\u043e\u0439. \u0421\u043e\u044e\u0437\u043d\u0438\u043a\u0438 \u043d\u0430 \u043f\u0443\u0442\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u044e\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u0445\u0438\u0442\u044b, \u0440\u0430\u0432\u043d\u044b\u0435 \u0443\u0440\u043e\u0432\u043d\u044e \u0431\u0430\u0440\u0434\u0430; \u0432\u0440\u0430\u0433\u0438 \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u044e\u0442 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0443\u044e \u0430\u0442\u0430\u043a\u0443 \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u0432\u0430\u0448\u0435\u0433\u043e \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u0445\u043e\u0434\u0430 \u0441 \u043f\u043e\u043c\u0435\u0445\u043e\u0439. \u041e\u0442\u043e\u0437\u0432\u0430\u043d\u043d\u044b\u0435 \u043a\u043b\u0438\u043d\u043a\u0438 \u0442\u0435\u0440\u044f\u044e\u0442 \u044d\u0444\u0444\u0435\u043a\u0442\u044b \u041c\u0430\u044d\u0441\u0442\u0440\u043e \u0438 \u0410\u043d\u0441\u0430\u043c\u0431\u043b\u044f, \u043a\u0440\u0443\u0436\u0430\u0442 \u0432\u043e\u043a\u0440\u0443\u0433 \u0432\u0430\u0441 \u0438 \u0434\u0430\u044e\u0442 +1 \u043a \u041a\u0414 \u043a\u0430\u0436\u0434\u044b\u0439. \u041f\u0440\u043e\u043f\u0430\u0434\u0430\u044e\u0442 \u0447\u0435\u0440\u0435\u0437 \u043c\u0438\u043d\u0443\u0442\u0443 \u0438\u043b\u0438 \u043f\u0440\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u043c \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0438.",!0))
