p=A.a([new A.J("ds_spec",1,"\u0414\u0430\u043b\u044c\u043d\u043e\u0431\u043e\u0439\u043d\u0430\u044f \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f","+1 \u043a \u0430\u0442\u0430\u043a\u0435 \u0438 \u0443\u0440\u043e\u043d\u0443 \u0434\u0430\u043b\u044c\u043d\u043e\u0431\u043e\u0439\u043d\u044b\u043c \u043e\u0440\u0443\u0436\u0438\u0435\u043c (\u0435\u0441\u043b\u0438 \u0443 \u043e\u0440\u0443\u0436\u0438\u044f \u043d\u0435\u0442 \u0441\u0432\u043e\u0435\u0433\u043e \u0431\u043e\u043d\u0443\u0441\u0430): +2 \u0441 9, +3 \u0441 17 \u0443\u0440\u043e\u0432\u043d\u044f. \u0421\u0432\u043e\u0439\u0441\u0442\u0432\u043e \xab\u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0430\xbb \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f.",!1),new A.J("ds_mark",1,"\u041e\u0442\u043c\u0435\u0442\u0438\u0442\u044c \u0446\u0435\u043b\u044c","\u0411\u043e\u043d\u0443\u0441\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442\u0435 \u0432\u0438\u0434\u0438\u043c\u043e\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u043e\u0440\u0443\u0436\u0438\u044f \u043d\u0430 1 \u043c\u0438\u043d\u0443\u0442\u0443: \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u043d\u0430 \u0412\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u0434\u043b\u044f \u0435\u0433\u043e \u043f\u043e\u0438\u0441\u043a\u0430, +\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0431\u043e\u043d\u0443\u0441\u0430 \u043c\u0430\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u0430 \u043a \u0443\u0440\u043e\u043d\u0443 \u043f\u043e \u043d\u0435\u043c\u0443; \u0440\u0435\u0430\u043a\u0446\u0438\u0435\u0439 \u043c\u043e\u0436\u043d\u043e \u0441\u043d\u044f\u0442\u044c \u043c\u0435\u0442\u043a\u0443 \u0440\u0430\u0434\u0438 \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043d\u0430 \u0434\u0430\u043b\u044c\u043d\u043e\u0431\u043e\u0439\u043d\u0443\u044e \u0430\u0442\u0430\u043a\u0443. \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0439 = \u0431\u043e\u043d\u0443\u0441\u0443 \u043c\u0430\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u0430 (\u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u043e\u0442\u0434\u044b\u0445).",!1),new A.J("ds_focus",2,"\u0421\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0435\u043d\u043d\u043e\u0441\u0442\u044c","\u041f\u0443\u043b \u043e\u0447\u043a\u043e\u0432 (\u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c 5): +1 \u0437\u0430 \u043f\u0435\u0440\u0432\u0443\u044e \u0434\u0430\u043b\u044c\u043d\u043e\u0431\u043e\u0439\u043d\u0443\u044e \u0430\u0442\u0430\u043a\u0443 \u0432 \u0445\u043e\u0434 \u0432 \u0431\u043e\u044e (\u043f\u043e\u043f\u0430\u0434\u0430\u043d\u0438\u0435 \u0438\u043b\u0438 \u043f\u0440\u043e\u043c\u0430\u0445), +1 \u0437\u0430 \u043c\u0438\u043d\u0443\u0442\u0443 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0446\u0438\u0438 (\u0440\u0430\u0437 \u0432 \u0447\u0430\u0441 \u0438\u043b\u0438 \u0434\u043e \u0438\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u044b). \u0421\u0433\u043e\u0440\u0430\u044e\u0442 \u043f\u043e\u0441\u043b\u0435 \u043e\u0442\u0434\u044b\u0445\u0430. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043e\u043f\u043e\u0440\u043d\u0443\u044e \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0438\u0441\u0442\u0438\u043a\u0443: \u0421\u043c\u0435\u043a\u0430\u043b\u043a\u0430 (\u0418\u043d\u0442), \u0412\u044b\u0434\u0435\u0440\u0436\u043a\u0430 (\u041c\u0434\u0440), \u0420\u0435\u0430\u043a\u0446\u0438\u044f (\u041b\u043e\u0432) \u0438\u043b\u0438 \u041a\u0443\u0440\u0430\u0436 (\u0425\u0430\u0440).",!1),new A.J("ds_deeds",2,"\u0422\u0440\u044e\u043a\u0438","\u0412\u044b \u0437\u043d\u0430\u0435\u0442\u0435 2 \u0442\u0440\u044e\u043a\u0430 (3 \u043d\u0430 5, 4 \u043d\u0430 9, 5 \u043d\u0430 13, 6 \u043d\u0430 17 \u0443\u0440\u043e\u0432\u043d\u0435), \u043f\u0440\u0438 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u0438 \u0443\u0440\u043e\u0432\u043d\u044f \u043e\u0434\u0438\u043d \u043c\u043e\u0436\u043d\u043e \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c. \u0421\u041b \u0442\u0440\u044e\u043a\u043e\u0432 = 8 + \u0411\u041c + \u043c\u043e\u0434. \u043e\u043f\u043e\u0440\u043d\u043e\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0438\u0441\u0442\u0438\u043a\u0438.\n\u0422\u0440\u044e\u043a\u0438 2 \u0443\u0440\u043e\u0432\u043d\u044f: \u0412\u0437\u0440\u044b\u0432\u043d\u043e\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (1 \u2014 \u0443\u0440\u043e\u043d \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u0430\u043c \xd72, \u0432\u044b\u0441\u0442\u0440\u0435\u043b \u0432\u043c\u0435\u0441\u0442\u043e \u0432\u0437\u043b\u043e\u043c\u0430), \u041f\u0435\u0440\u0435\u043a\u0430\u0442 (\u0440\u0435\u0430\u043a\u0446\u0438\u044f: +1 \u043a \u041a\u0414 \u0438\u043b\u0438 \u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043a\u0443 \u041b\u043e\u0432 \u0437\u0430 \u043e\u0447\u043a\u043e), \u041f\u043e\u043b\u0435 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u044f (1, \u0431\u043e\u043d\u0443\u0441\u043d\u043e\u0435, \u043a\u043e\u043d\u0446. 1 \u043c\u0438\u043d: \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u043d\u0430 \u0412\u043d\u0438\u043c\u0430\u043d\u0438\u0435, \u0410\u043d\u0430\u043b\u0438\u0437, \u0412\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u0435, \u041f\u0440\u043e\u043d\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c), \u0412\u0435\u0435\u0440 \u0432\u044b\u0441\u0442\u0440\u0435\u043b\u043e\u0432 (\u0434\u043e\u043f. \u0430\u0442\u0430\u043a\u0438 \u043f\u043e \u0447\u0438\u0441\u043b\u0443 \u043e\u0447\u043a\u043e\u0432, \u0431\u0435\u0437 \u043c\u043e\u0434. \u043a \u0443\u0440\u043e\u043d\u0443), \u0427\u0443\u0442\u044c\u0451 \u0441\u0442\u0440\u0435\u043b\u043a\u0430 (2 \u2014 +\u043a6 \u043a \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0435), \u0414\u043e\u0437\u043e\u0440 (1, \u0440\u0435\u0430\u043a\u0446\u0438\u044f: \u0430\u0442\u0430\u043a\u0430 \u043f\u043e \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443, \u0430\u0442\u0430\u043a\u0443\u044e\u0449\u0435\u043c\u0443 \u043d\u0435 \u0432\u0430\u0441), \u041e\u0442\u0442\u0430\u043b\u043a\u0438\u0432\u0430\u044e\u0449\u0438\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (\u0421\u0438\u043b-\u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043e\u043a \u0438\u043b\u0438 \u0442\u043e\u043b\u0447\u043e\u043a 10 \u0444\u0442 \u0437\u0430 \u043e\u0447\u043a\u043e), \u0411\u0435\u0433\u043b\u044b\u0439 \u043e\u0433\u043e\u043d\u044c (1 \u2014 \u0434\u043e\u043f. \u0430\u0442\u0430\u043a\u0430 \u0431\u043e\u043d\u0443\u0441\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c), \u041e\u0442\u0432\u0435\u0442 (1, \u0440\u0435\u0430\u043a\u0446\u0438\u044f \u043d\u0430 \u0430\u0442\u0430\u043a\u0443 \u043f\u043e \u0432\u0430\u043c), \u0421\u0442\u043e\u0439\u043a\u0430 \u0441\u043d\u0430\u0439\u043f\u0435\u0440\u0430 (1 \u2014 \u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \xd72 \u043d\u0430 \u043c\u0438\u043d\u0443\u0442\u0443), \u041f\u043e\u0434\u0441\u0435\u0447\u043a\u0430 (1 \u2014 \u0421\u0438\u043b \u0438\u043b\u0438 \u043d\u0438\u0447\u043a\u043e\u043c), \u0416\u0438\u0437\u043d\u0435\u043d\u043d\u044b\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (+\u043a\u043e\u0441\u0442\u044c \u0443\u0440\u043e\u043d\u0430 \u0437\u0430 \u043e\u0447\u043a\u043e), \u041e\u0442\u0445\u043e\u0434 (1 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u0438 \u0431\u0435\u0437 \u043f\u0440\u043e\u0432\u043e\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f).\n\u0421 5 \u0443\u0440\u043e\u0432\u043d\u044f: \u041e\u0433\u043b\u0443\u0448\u0430\u044e\u0449\u0438\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (3 \u2014 \u0422\u0435\u043b \u0438\u043b\u0438 \u043e\u0448\u0435\u043b\u043e\u043c\u043b\u0451\u043d), \u041e\u0442\u0432\u043e\u0434\u044f\u0449\u0438\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (+1 \u041a\u0414 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0443 \u0437\u0430 \u043e\u0447\u043a\u043e), \u0421\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0435\u043d\u043d\u044b\u0439 \u043e\u0433\u043e\u043d\u044c, \u0423\u0441\u0442\u0440\u0430\u0448\u0430\u044e\u0449\u0438\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (2 \u2014 \u041c\u0434\u0440 \u0438\u043b\u0438 \u0438\u0441\u043f\u0443\u0433\u0430\u043d), \u041a\u0440\u043e\u0432\u043e\u0442\u0435\u0447\u0435\u043d\u0438\u0435 (3).\n\u0421 9 \u0443\u0440\u043e\u0432\u043d\u044f: \u041e\u0431\u0441\u0442\u0440\u0435\u043b (3 \u2014 \u043e\u0431\u043b\u0430\u0441\u0442\u044c 10 \u0444\u0442, \u041b\u043e\u0432), \u0425\u043b\u0430\u0434\u043d\u043e\u043a\u0440\u043e\u0432\u0438\u0435 (1 \u2014 \u0441\u043d\u044f\u0442\u044c \u043e\u0447\u0430\u0440\u043e\u0432\u0430\u043d\u0438\u0435/\u0438\u0441\u043f\u0443\u0433), \u041f\u0440\u043e\u0431\u0438\u0432\u0430\u044e\u0449\u0438\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b (3 \u2014 \u043b\u0438\u043d\u0438\u044f), \u0420\u0438\u043a\u043e\u0448\u0435\u0442 (2 \u2014 \u043f\u0435\u0440\u0435\u0431\u0440\u043e\u0441 \u043f\u043e \u0434\u0440\u0443\u0433\u043e\u0439 \u0446\u0435\u043b\u0438), \u0421\u0442\u043e\u0439\u043a\u043e\u0441\u0442\u044c (1).\n\u0421 13 \u0443\u0440\u043e\u0432\u043d\u044f: \u041e\u0431\u043c\u0430\u043d \u0441\u043c\u0435\u0440\u0442\u0438 (2 \u2014 \u043e\u0441\u0442\u0430\u0442\u044c\u0441\u044f \u0441 1 \u0445\u0438\u0442\u043e\u043c), \u041c\u043e\u043b\u043d\u0438\u0435\u043d\u043e\u0441\u043d\u0430\u044f \u0440\u0435\u0430\u043a\u0446\u0438\u044f (1 \u2014 \u0432\u0442\u043e\u0440\u0430\u044f \u0440\u0435\u0430\u043a\u0446\u0438\u044f \u0437\u0430 \u0440\u0430\u0443\u043d\u0434).",!1),new A.J("ds_trail",3,"\u0422\u0440\u043e\u043f\u0430 \u0434\u0435\u0441\u043f\u0435\u0440\u0430\u0434\u043e","\u0412\u044b \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0442\u0440\u043e\u043f\u0443 \u2014 \u043e\u043d\u0430 \u0434\u0430\u0451\u0442 \u0443\u043c\u0435\u043d\u0438\u044f \u0438 \u0434\u0432\u0430 \u0431\u043e\u043d\u0443\u0441\u043d\u044b\u0445 \u0442\u0440\u044e\u043a\u0430 \u043d\u0430 3, 7, 11 \u0438 15 \u0443\u0440\u043e\u0432\u043d\u044f\u0445.",!1)],a6)
